/* saturn_music.h -- music stream: libcd's XA calls (CdlSetfilter, CdlReadS /
 * CdlReadN with CdlModeRT, CdlPause, CdlStop; LibRef47 p0677-0678) play the
 * title's converted PCM through the CD owner (saturn_cd) and the sound seam
 * (saturn_spu.h stream). The title supplies saturn_music_map[] (generated by
 * tools/media/mus_conv.py --map-c) and links saturn.mk
 * PSYZ_SATURN_MUSIC_SRCS; without them saturn_libcd.c's weak hooks keep every
 * call as before. */
#ifndef SATURN_MUSIC_H
#define SATURN_MUSIC_H

#include <stdint.h>

/* one converted XA channel: the PS1 file's sectors and the Saturn PCM file
 * (units of 32,768 B, each the left half then the right; format 0 PCM8, 1
 * PCM16 big-endian) */
typedef struct {
    uint32_t xa_lba, xa_sectors, file, chan, stride, phase;
    uint32_t pcm_fad, pcm_bytes, format, rate, channels, unit_bytes;
    uint32_t frames, crc32;
} saturn_music_rec_t;

extern const saturn_music_rec_t saturn_music_map[];
extern const int saturn_music_map_n;

typedef struct {
    uint32_t underrun; /* steps playing with lead < LEAD and nothing landed */
    /* landed-not-written + sound lead, bytes per channel, from the first
     * time MUSIC_HIGH units were landed */
    uint32_t cover_min;
    uint32_t units;    /* units landed */
    uint32_t restarts; /* ReadS / ReadN hits while the stream played */
    uint32_t nofilter; /* hits without CdlModeSF */
    uint32_t slices;   /* title read ops issued beside the stream */
} saturn_music_stats_t;

const saturn_music_stats_t* saturn_music_stats(void);

/* saturn_libcd.c's hooks (weak no-op defaults there) */
/* 1 on a hit; chan -1 without CdlModeSF */
int saturn_music_read(uint32_t fad, int chan);
void saturn_music_end(void);
int saturn_music_on(void); /* 0 off, 1 on, 2 on with its unit read in flight */
void saturn_music_step(void); /* once per service poll while on */
void saturn_music_slice(void);

#endif
